package com.smarthire.backend.interview.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.core.io.ByteArrayResource; import org.springframework.core.io.Resource; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import software.amazon.awssdk.core.sync.RequestBody; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.s3.S3Client; import software.amazon.awssdk.services.s3.model.GetObjectRequest; import software.amazon.awssdk.services.s3.model.PutObjectRequest; import java.io.IOException; import java.net.URI; import java.util.UUID;
@Service @ConditionalOnProperty(name="app.recording.storage.provider", havingValue="s3") public class S3RecordingStorageService implements RecordingStorageService { private final S3Client s3; private final String bucket; public S3RecordingStorageService(@Value("${app.recording.storage.s3.bucket:}") String bucket,@Value("${app.recording.storage.s3.region:us-east-1}") String region,@Value("${app.recording.storage.s3.endpoint:}") String endpoint,@Value("${app.recording.storage.s3.path-style:false}") boolean pathStyle){if(bucket==null||bucket.isBlank())throw new IllegalStateException("S3_BUCKET is required when RECORDING_STORAGE_PROVIDER=s3."); var b=S3Client.builder().region(Region.of(region)); if(endpoint!=null&&!endpoint.isBlank())b.endpointOverride(URI.create(endpoint)); if(pathStyle)b.forcePathStyle(true); s3=b.build(); this.bucket=bucket;} public String store(Long interviewId,Long sessionId,String kind,MultipartFile file)throws IOException{if(file==null||file.isEmpty())throw new IOException("No file provided for recording upload."); String key="recordings/"+interviewId+"/"+sessionId+"/"+kind+"-"+UUID.randomUUID()+ext(file.getOriginalFilename(),file.getContentType()); try{s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(file.getContentType()).build(),RequestBody.fromInputStream(file.getInputStream(),file.getSize()));return key;}catch(Exception e){throw new IOException("Failed to store recording in object storage.",e);}} public Resource load(String key)throws IOException{if(key==null||key.isBlank())throw new IOException("Recording key is missing."); try{byte[] data=s3.getObjectAsBytes(GetObjectRequest.builder().bucket(bucket).key(key).build()).asByteArray(); return new ByteArrayResource(data){public String getFilename(){return key.substring(key.lastIndexOf('/')+1);}};}catch(Exception e){throw new IOException("Failed to load recording from object storage.",e);}} private String ext(String name,String type){if(name!=null&&name.contains("."))return name.substring(name.lastIndexOf('.')); if(type!=null){if(type.contains("webm"))return ".webm";if(type.contains("mp4"))return ".mp4";if(type.contains("mpeg")||type.contains("mp3"))return ".mp3";}return ".bin";} }
